}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function HospitalSystemCloutVsCommercialPrices2026Dashboard() {
  const [view, setView] = useState<ViewId>("bands");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [scatterMetric, setScatterMetric] = useState<ScatterMetric>("ratio");

  const bandBars = useMemo(
    () =>
      HHI_BANDS.map((b, i) => ({
        name: b.label,
        range: b.hhiRange,
        mean: b.meanRatioPct,
        p25: b.p25RatioPct,
        p75: b.p75RatioPct,
        top1: b.meanTop1SharePct,
        fill: BAND_COLORS[i],
        cbsas: b.cbsaCount,
      })),
    [],
  );

  const scatter = useMemo(() => {
    return metrosByRegion(region).map((m) => ({
      ...m,
      x: m.hhi,
      y:
        scatterMetric === "ratio"
          ? m.ratioPct
          : scatterMetric === "top1"
            ? m.top1SharePct
            : m.top2SharePct,
      z: Math.max(80, m.employerLivesK / 8),
      fill: REGION_COLORS[m.region],
    }));
  }, [region, scatterMetric]);

