    () =>
      BEFORE_AFTER_BANDS.map((b) => ({
        name: b.band,
        before: b.beforeMedianMin,
        after: b.afterMedianMin,
        counties: b.counties,
      })),
    [],
  );

  const scatter = useMemo(() => {
    let rows = countiesByRegion(region);
    rows = [...rows].sort((a, b) => {
      if (countySort === "added") return b.addedMin - a.addedMin;
      if (countySort === "after") return b.driveAfterMin - a.driveAfterMin;
      return b.popK - a.popK;
    });
    return rows.map((c) => ({
      ...c,
      x: c.popK,
      y: countyMetric === "minutes" ? c.addedMin : c.addedMiles,
      z: Math.max(60, c.ruralSharePct),
      fill: REGION_COLORS[c.region],
      label: `${c.county}, ${c.stateAbbr}`,
    }));
  }, [region, countySort, countyMetric]);

  const facilityBars = useMemo(
    () =>
      FACILITY_MIX.map((f, i) => ({
        name: f.label,
        share: f.sharePct,
        closures: f.closures,
        fill: [TEAL, AMBER, SLATE][i],
      })),
