                  yAxisId="left"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Annual", angle: -90, position: "insideLeft", style: { fontSize: 11 } }}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Cumulative", angle: 90, position: "insideRight", style: { fontSize: 11 } }}
