                <Tooltip />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="complete"
                  name="Complete closure"
                  stackId="a"
                  fill={ROSE}
                  stroke={ROSE}
                  fillOpacity={0.7}
                />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="conversion"
                  name="Conversion"
                  stackId="a"
                  fill={AMBER}
                  stroke={AMBER}
                  fillOpacity={0.65}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="cumulative"
                  name="Cumulative"
                  stroke={NAVY}
                  strokeWidth={2.5}
                  dot={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Peak annual wave around {ANALYTICS.peakYear} (~{ANALYTICS.peakYearClosures}{" "}
            events). South holds ~{ANALYTICS.southClosureSharePct}% of the stock.
          </p>
        </ChartCard>
      )}

      {view === "regions" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Region rollup"
            subtitle="Closures and median added drive minutes"
