                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="closures" name="Closures" radius={[4, 4, 0, 0]}>
                    {regionBars.map((r) => (
                      <Cell key={r.name} fill={r.fill} />
                    ))}
                  </Bar>
                  <Bar dataKey="medianMin" name="Median +min" fill={SLATE} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="State ladder"
            subtitle={
              region === "all"
                ? "Top states by Sheps closure count"
                : `${region} states by closure count`
            }
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={stateBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis type="category" dataKey="name" width={36} tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="closures" name="Closures" radius={[0, 4, 4, 0]}>
                    {stateBars.map((s) => (
                      <Cell key={s.name} fill={s.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "buckets" && (
        <ChartCard
          title="Added drive-time buckets"
          subtitle="Counties that lost their nearest hospital ??? desk road-network minutes"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={bucketBars} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
