"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ANALYTICS,
  BEFORE_AFTER_BANDS,
  CLOSURE_PATH,
  COUNTY_PANEL,
  DRIVE_BUCKETS,
  FACILITY_MIX,
  HEADLINE,
  REGION_ROLLUP,
  SOURCE_NOTE,
  countiesByRegion,
  fmtInt,
  fmtMin,
  fmtPct,
  statesByRegion,
  type RegionId,
} from "@/data/rural-hospital-closures-and-drive-times-2026-data";

// viz-types: composed area+line (closure path), stacked region bars,
// drive-bucket bars, before/after dual bars, county scatter, facility pie-bars
// | layout: default | controls: view, region, sort/metric

type ViewId = "path" | "regions" | "buckets" | "beforeAfter" | "counties" | "facility";
type RegionFilter = "all" | RegionId;
type CountySort = "added" | "after" | "pop";
type CountyMetric = "minutes" | "miles";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";

const REGION_COLORS: Record<string, string> = {
  Northeast: INDIGO,
  Midwest: TEAL,
  South: ROSE,
  West: AMBER,
};

const BUCKET_COLORS = [SKY, TEAL, AMBER, "#ea580c", ROSE];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function RuralHospitalClosuresAndDriveTimes2026Dashboard() {
  const [view, setView] = useState<ViewId>("path");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [countySort, setCountySort] = useState<CountySort>("added");
  const [countyMetric, setCountyMetric] = useState<CountyMetric>("minutes");

  const pathData = useMemo(
    () =>
      CLOSURE_PATH.map((r) => ({
        year: String(r.year),
        complete: r.complete,
        conversion: r.conversion,
        annual: r.complete + r.conversion,
        cumulative: r.cumulative,
      })),
    [],
  );

  const regionBars = useMemo(
    () =>
      REGION_ROLLUP.map((r) => ({
        name: r.region,
        closures: r.closures,
        counties: r.countiesAffected,
        medianMin: r.medianAddedMin,
        meanMin: r.meanAddedMin,
        residentsK: r.residentsK,
        fill: REGION_COLORS[r.region],
      })),
    [],
  );

  const stateBars = useMemo(() => {
    const rows = statesByRegion(region);
    return [...rows]
      .sort((a, b) => b.closures - a.closures)
      .slice(0, 12)
      .map((s) => ({
        name: s.stateAbbr,
        full: s.state,
        closures: s.closures,
        medianMin: s.medianAddedMin,
        fill: REGION_COLORS[s.region],
      }));
  }, [region]);

  const bucketBars = useMemo(
    () =>
      DRIVE_BUCKETS.map((b, i) => ({
        name: b.label,
        counties: b.countyCount,
        residentsK: b.residentsK,
        share: b.shareOfCountiesPct,
        fill: BUCKET_COLORS[i],
      })),
    [],
  );

  const beforeAfter = useMemo(
    () =>
      BEFORE_AFTER_BANDS.map((b) => ({
        name: b.band,
        before: b.beforeMedianMin,
        after: b.afterMedianMin,
        counties: b.counties,
      })),
    [],
  );

  const scatter = useMemo(() => {
    let rows = countiesByRegion(region);
    rows = [...rows].sort((a, b) => {
      if (countySort === "added") return b.addedMin - a.addedMin;
      if (countySort === "after") return b.driveAfterMin - a.driveAfterMin;
      return b.popK - a.popK;
    });
    return rows.map((c) => ({
      ...c,
      x: c.popK,
      y: countyMetric === "minutes" ? c.addedMin : c.addedMiles,
      z: Math.max(60, c.ruralSharePct),
      fill: REGION_COLORS[c.region],
      label: `${c.county}, ${c.stateAbbr}`,
    }));
  }, [region, countySort, countyMetric]);

  const facilityBars = useMemo(
    () =>
      FACILITY_MIX.map((f, i) => ({
        name: f.label,
        share: f.sharePct,
        closures: f.closures,
        fill: [TEAL, AMBER, SLATE][i],
      })),
    [],
  );

  return (
    <div className="w-full space-y-4">
      <div className="rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 sm:px-5">
        <p className="text-sm text-slate-700">
          <span className="font-semibold text-slate-900">
            Added drive minutes post-closure.
          </span>{" "}
          Sheps-tracked rural closures since 2005:{" "}
          <span className="font-semibold">{fmtInt(HEADLINE.closuresSince2005)}</span>
          . Counties that lost their nearest acute/ED facility:{" "}
          <span className="font-semibold">
            {fmtInt(HEADLINE.countiesLostNearest)}
          </span>
          . Desk median added road time:{" "}
          <span className="font-semibold">
            {fmtMin(HEADLINE.medianAddedMinutes)}
          </span>{" "}
          (P75 {fmtMin(HEADLINE.p75AddedMinutes)};{" "}
          {fmtInt(HEADLINE.tipCounties45Plus)} counties ???45 min). ~
          {HEADLINE.residentsAffectedM}M residents in affected counties.
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "path", label: "Closure path" },
            { id: "regions", label: "Regions + states" },
            { id: "buckets", label: "Drive buckets" },
            { id: "beforeAfter", label: "Before / after" },
            { id: "counties", label: "County scatter" },
            { id: "facility", label: "Facility mix" },
          ]}
        />
        <ToggleGroup
          label="Region"
          value={region}
          onChange={setRegion}
          options={[
            { id: "all", label: "All" },
            { id: "South", label: "South" },
            { id: "Midwest", label: "Midwest" },
            { id: "West", label: "West" },
            { id: "Northeast", label: "Northeast" },
          ]}
        />
      </div>

      {view === "path" && (
        <ChartCard
          title="Rural closures and conversions since 2005"
          subtitle="Annual complete closures vs conversions; cumulative Sheps-aligned path"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={pathData} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} interval={2} />
                <YAxis
                  yAxisId="left"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Annual", angle: -90, position: "insideLeft", style: { fontSize: 11 } }}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Cumulative", angle: 90, position: "insideRight", style: { fontSize: 11 } }}
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="complete"
                  name="Complete closure"
                  stackId="a"
                  fill={ROSE}
                  stroke={ROSE}
                  fillOpacity={0.7}
                />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="conversion"
                  name="Conversion"
                  stackId="a"
                  fill={AMBER}
                  stroke={AMBER}
                  fillOpacity={0.65}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="cumulative"
                  name="Cumulative"
                  stroke={NAVY}
                  strokeWidth={2.5}
                  dot={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Peak annual wave around {ANALYTICS.peakYear} (~{ANALYTICS.peakYearClosures}{" "}
            events). South holds ~{ANALYTICS.southClosureSharePct}% of the stock.
          </p>
        </ChartCard>
      )}

      {view === "regions" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Region rollup"
            subtitle="Closures and median added drive minutes"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={regionBars} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="closures" name="Closures" radius={[4, 4, 0, 0]}>
                    {regionBars.map((r) => (
                      <Cell key={r.name} fill={r.fill} />
                    ))}
                  </Bar>
                  <Bar dataKey="medianMin" name="Median +min" fill={SLATE} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="State ladder"
            subtitle={
              region === "all"
                ? "Top states by Sheps closure count"
                : `${region} states by closure count`
            }
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={stateBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis type="category" dataKey="name" width={36} tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="closures" name="Closures" radius={[0, 4, 4, 0]}>
                    {stateBars.map((s) => (
                      <Cell key={s.name} fill={s.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "buckets" && (
        <ChartCard
          title="Added drive-time buckets"
          subtitle="Counties that lost their nearest hospital ??? desk road-network minutes"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={bucketBars} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis yAxisId="left" tick={{ fontSize: 11 }} />
                <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 11 }} />
                <Tooltip />
                <Legend />
                <Bar yAxisId="left" dataKey="counties" name="Counties" radius={[4, 4, 0, 0]}>
                  {bucketBars.map((b) => (
                    <Cell key={b.name} fill={b.fill} />
                  ))}
                </Bar>
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="residentsK"
                  name="Residents (000s)"
                  stroke={NAVY}
                  strokeWidth={2}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Tip share (???45 min): {fmtPct(ANALYTICS.tipSharePct)} of affected counties.
            Median added time: {fmtMin(HEADLINE.medianAddedMinutes)}.
          </p>
        </ChartCard>
      )}

      {view === "beforeAfter" && (
        <ChartCard
          title="Nearest ED minutes ??? before vs after"
          subtitle="Median road minutes by ACS rurality band for counties that lost nearest facility"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={beforeAfter} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} unit=" min" />
                <Tooltip />
                <Legend />
                <Bar dataKey="before" name="Before" fill={TEAL} radius={[4, 4, 0, 0]} />
                <Bar dataKey="after" name="After" fill={ROSE} radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "counties" && (
        <ChartCard
          title="County panel ??? population vs added access cost"
          subtitle="Tip counties in the desk GIS panel (filter by region; sort and Y metric below)"
        >
          <div className="mb-3 flex flex-wrap gap-3">
            <ToggleGroup
              label="Sort"
              value={countySort}
              onChange={setCountySort}
              options={[
                { id: "added", label: "Added time" },
                { id: "after", label: "After time" },
                { id: "pop", label: "Population" },
              ]}
            />
            <ToggleGroup
              label="Y metric"
              value={countyMetric}
              onChange={setCountyMetric}
              options={[
                { id: "minutes", label: "Added minutes" },
                { id: "miles", label: "Added miles" },
              ]}
            />
          </div>
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Pop (k)"
                  tick={{ fontSize: 11 }}
                  label={{ value: "County pop (000s)", position: "insideBottom", offset: -2, style: { fontSize: 11 } }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Added"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: countyMetric === "minutes" ? "Added minutes" : "Added miles",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11 },
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[60, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0]?.payload as (typeof scatter)[0];
                    if (!d) return null;
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-md">
                        <div className="font-semibold text-slate-900">{d.label}</div>
                        <div className="text-slate-600">
                          +{d.addedMin} min ?? after {d.driveAfterMin} min ?? pop{" "}
                          {d.popK}k ?? {d.yearClosed} ({d.kind})
                        </div>
                      </div>
                    );
                  }}
                />
                <Scatter data={scatter} fill={TEAL}>
                  {scatter.map((p) => (
                    <Cell key={p.label} fill={p.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Showing {scatter.length} of {COUNTY_PANEL.length} tip counties in panel.
            Bubble size scales with rural share.
          </p>
        </ChartCard>
      )}

      {view === "facility" && (
        <ChartCard
          title="Facility type mix among closures"
          subtitle="Critical Access vs PPS short-term vs other rural acute (Sheps-aligned share)"
        >
          <div className="h-[320px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={facilityBars} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis tick={{ fontSize: 11 }} unit="%" />
                <Tooltip />
                <Bar dataKey="share" name="Share of closures (%)" radius={[4, 4, 0, 0]}>
                  {facilityBars.map((f) => (
                    <Cell key={f.name} fill={f.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            CAH share ??? {fmtPct(HEADLINE.cahSharePct)}. Only-hospital counties ???{" "}
            {fmtPct(ANALYTICS.onlyHospitalSharePct)} of the affected set.
          </p>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

