/**
 * QA: rural-hospital-closures-and-drive-times-2026
 * // viz-types: composed area+line, stacked/region bars, drive-bucket composed,
 * // before/after dual bars, county scatter, facility bars | layout: default
 * // smoke-marker: Added drive minutes post-closure
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  ANALYTICS,
  BEFORE_AFTER_BANDS,
  CLOSURE_PATH,
  COUNTY_PANEL,
  DRIVE_BUCKETS,
  FACILITY_MIX,
  HEADLINE,
  REGION_ROLLUP,
  STATE_PANEL,
} from "../src/data/rural-hospital-closures-and-drive-times-2026-data.ts";

assert.equal(HEADLINE.closuresSince2005, 192);
assert.equal(HEADLINE.countiesLostNearest, 214);
assert.equal(HEADLINE.medianAddedMinutes, 22);
assert.equal(HEADLINE.tipCounties45Plus, 41);
assert.equal(HEADLINE.completeClosures + HEADLINE.conversions, 192);
assert.ok(CLOSURE_PATH.length >= 15);
assert.ok(REGION_ROLLUP.length === 4);
assert.ok(STATE_PANEL.length >= 12);
assert.ok(DRIVE_BUCKETS.length === 5);
assert.ok(COUNTY_PANEL.length >= 12);
assert.ok(BEFORE_AFTER_BANDS.length === 4);
assert.ok(FACILITY_MIX.length === 3);
assert.ok(ANALYTICS.tipSharePct > 10);
assert.ok(ANALYTICS.southClosureSharePct > 40);

const root = process.cwd();
const slug = "rural-hospital-closures-and-drive-times-2026";
const markers = ["Added drive minutes post-closure", "22"];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4186);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({
        state: "attached",
        timeout: 20000,
      });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Regions + states");
    await clickBtn(page, "South");
    await clickBtn(page, "All");
    await clickBtn(page, "Drive buckets");
    await clickBtn(page, "Before / after");
    await clickBtn(page, "County scatter");
    await clickBtn(page, "Added miles");
    await clickBtn(page, "Added minutes");
    await clickBtn(page, "Population");
    await clickBtn(page, "Facility mix");
    await clickBtn(page, "Closure path");
    console.log("??? auditVizInteractions");
    const audit = await auditVizInteractions(page);
    if (audit.issues.length > 0) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    console.log("??? viz interaction audit");
    console.log("??? QA passed:", slug);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

